<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Bouncing Ball Physics Playground</title>
    <style>
        :root {
            --bg: #0f0f1a;
            --surface: #1a1a2e;
            --canvas-bg: #141428;
            --text: #e0e0e0;
            --accent: #6c5ce7;
            --accent-hover: #7d6ff0;
            --danger: #e74c3c;
            --danger-hover: #f06050;
            --warning: #f39c12;
            --warning-hover: #f5a623;
            --border: #2a2a40;
            --shadow: 0 0 30px rgba(108, 92, 231, 0.25);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: var(--bg);
            display: flex;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            font-family: 'Segoe UI', 'Inter', system-ui, -apple-system, sans-serif;
            user-select: none;
            -webkit-user-select: none;
            -webkit-tap-highlight-color: transparent;
        }

        .container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
        }

        .header {
            display: flex;
            align-items: center;
            gap: 12px;
            color: var(--text);
            font-size: 1.4rem;
            font-weight: 600;
            letter-spacing: 0.02em;
            opacity: 0.9;
        }
        .header .dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: var(--accent);
            animation: pulse 1.8s ease-in-out infinite;
        }
        @keyframes pulse {
            0%,
            100% {
                box-shadow: 0 0 6px var(--accent), 0 0 14px var(--accent);
            }
            50% {
                box-shadow: 0 0 2px var(--accent), 0 0 6px var(--accent);
            }
        }

        .canvas-wrapper {
            position: relative;
            border-radius: 16px;
            overflow: hidden;
            box-shadow: var(--shadow), 0 0 0 1px var(--border);
            transition: box-shadow 0.3s ease;
            cursor: crosshair;
            line-height: 0;
        }
        .canvas-wrapper:hover {
            box-shadow: 0 0 40px rgba(108, 92, 231, 0.4), 0 0 0 1px rgba(108, 92, 231, 0.5);
        }
        .canvas-wrapper:active {
            box-shadow: 0 0 20px rgba(108, 92, 231, 0.5), 0 0 0 2px rgba(108, 92, 231, 0.7);
        }

        canvas {
            display: block;
            width: 500px;
            height: 500px;
            background: var(--canvas-bg);
            border-radius: 16px;
        }

        .btn-row {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            justify-content: center;
        }

        button {
            padding: 12px 24px;
            font-size: 0.95rem;
            font-weight: 600;
            letter-spacing: 0.03em;
            border: none;
            border-radius: 10px;
            cursor: pointer;
            transition: all 0.2s ease;
            outline: none;
            font-family: inherit;
            position: relative;
            overflow: hidden;
        }
        button:active {
            transform: scale(0.95);
        }

        #drop {
            background: var(--accent);
            color: #fff;
            box-shadow: 0 4px 16px rgba(108, 92, 231, 0.35);
        }
        #drop:hover {
            background: var(--accent-hover);
            box-shadow: 0 6px 22px rgba(108, 92, 231, 0.5);
            transform: translateY(-1px);
        }

        #play {
            background: var(--warning);
            color: #1a1a1a;
            box-shadow: 0 4px 16px rgba(243, 156, 18, 0.3);
            min-width: 110px;
        }
        #play:hover {
            background: var(--warning-hover);
            box-shadow: 0 6px 22px rgba(243, 156, 18, 0.45);
            transform: translateY(-1px);
        }
        #play.paused {
            background: #2ecc71;
            box-shadow: 0 4px 16px rgba(46, 204, 113, 0.3);
        }
        #play.paused:hover {
            background: #3ddb84;
            box-shadow: 0 6px 22px rgba(46, 204, 113, 0.45);
        }

        #clear {
            background: var(--danger);
            color: #fff;
            box-shadow: 0 4px 16px rgba(231, 76, 60, 0.25);
        }
        #clear:hover {
            background: var(--danger-hover);
            box-shadow: 0 6px 22px rgba(231, 76, 60, 0.4);
            transform: translateY(-1px);
        }

        .ball-count {
            color: var(--text);
            font-size: 0.85rem;
            opacity: 0.6;
            letter-spacing: 0.04em;
            text-transform: uppercase;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <span class="dot"></span>
            Ball Physics
        </div>
        <div class="canvas-wrapper">
            <canvas id="sim" width="500" height="500"></canvas>
        </div>
        <div class="btn-row">
            <button id="drop">⬇ Drop Ball</button>
            <button id="play">⏸ Pause</button>
            <button id="clear">✕ Clear</button>
        </div>
        <div class="ball-count" id="ball-count">0 balls</div>
    </div>

    <script>
        (function() {
            // ─────────────────────────────────────
            // Constants
            // ─────────────────────────────────────
            const CANVAS_SIZE = 500;
            const GRAVITY = 500; // pixels per second²
            const RESTITUTION = 0.72;
            const DEFAULT_RADIUS = 18;
            const MAX_SUBSTEP = 1 / 60; // ~16.7ms per substep

            // Ball color palette (vibrant, dark-theme friendly)
            const BALL_COLORS = [
                '#ff6b6b', '#ff8e72', '#feca57', '#ff9ff3',
                '#54a0ff', '#5f27cd', '#01a3a4', '#f368e0',
                '#ff6348', '#7bed9f', '#70a1ff', '#ffa502',
                '#e056a0', '#0abde3', '#10ac84', '#ee5a24',
                '#6c5ce7', '#fd79a8', '#00cec9', '#e17055',
            ];

            // ─────────────────────────────────────
            // DOM Elements
            // ─────────────────────────────────────
            const canvas = document.getElementById('sim');
            const ctx = canvas.getContext('2d');
            const dropBtn = document.getElementById('drop');
            const playBtn = document.getElementById('play');
            const clearBtn = document.getElementById('clear');
            const ballCountEl = document.getElementById('ball-count');

            // ─────────────────────────────────────
            // State
            // ─────────────────────────────────────
            let balls = [];
            let animating = true;
            let lastTime = null;
            let animationId = null;

            // ─────────────────────────────────────
            // Utility Functions
            // ─────────────────────────────────────
            function randomBallColor() {
                return BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)];
            }

            function hexToRgb(hex) {
                const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                return result ? {
                    r: parseInt(result[1], 16),
                    g: parseInt(result[2], 16),
                    b: parseInt(result[3], 16),
                } : { r: 200, g: 200, b: 200 };
            }

            function lightenHex(hex, factor) {
                const { r, g, b } = hexToRgb(hex);
                const lr = Math.min(255, Math.round(r + (255 - r) * factor));
                const lg = Math.min(255, Math.round(g + (255 - g) * factor));
                const lb = Math.min(255, Math.round(b + (255 - b) * factor));
                return `rgb(${lr},${lg},${lb})`;
            }

            function darkenHex(hex, factor) {
                const { r, g, b } = hexToRgb(hex);
                const dr = Math.round(r * (1 - factor));
                const dg = Math.round(g * (1 - factor));
                const db = Math.round(b * (1 - factor));
                return `rgb(${dr},${dg},${db})`;
            }

            // ─────────────────────────────────────
            // Rendering
            // ─────────────────────────────────────
            function render() {
                // Clear canvas
                ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

                // Background fill
                ctx.fillStyle = '#141428';
                ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

                // Subtle grid
                ctx.strokeStyle = 'rgba(255,255,255,0.03)';
                ctx.lineWidth = 1;
                const gridSpacing = 50;
                for (let gx = gridSpacing; gx < CANVAS_SIZE; gx += gridSpacing) {
                    ctx.beginPath();
                    ctx.moveTo(gx, 0);
                    ctx.lineTo(gx, CANVAS_SIZE);
                    ctx.stroke();
                }
                for (let gy = gridSpacing; gy < CANVAS_SIZE; gy += gridSpacing) {
                    ctx.beginPath();
                    ctx.moveTo(0, gy);
                    ctx.lineTo(CANVAS_SIZE, gy);
                    ctx.stroke();
                }

                // Draw all balls
                for (const ball of balls) {
                    drawBall(ball);
                }

                // Update ball count display
                ballCountEl.textContent = `${balls.length} ball${balls.length !== 1 ? 's' : ''}`;
            }

            function drawBall(ball) {
                const { x, y, r, color } = ball;

                // Soft shadow beneath the ball
                ctx.save();
                ctx.fillStyle = 'rgba(0,0,0,0.35)';
                ctx.beginPath();
                ctx.ellipse(x + 2, y + 3, r * 0.85, r * 0.6, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();

                // Main sphere with radial gradient (3D effect)
                const gradient = ctx.createRadialGradient(
                    x - r * 0.3, y - r * 0.35, r * 0.05,
                    x, y, r
                );
                const lightColor = lightenHex(color, 0.55);
                const midColor = lightenHex(color, 0.15);
                const darkColor = darkenHex(color, 0.35);
                gradient.addColorStop(0, lightColor);
                gradient.addColorStop(0.35, midColor);
                gradient.addColorStop(0.75, color);
                gradient.addColorStop(1, darkColor);

                ctx.fillStyle = gradient;
                ctx.beginPath();
                ctx.arc(x, y, r, 0, Math.PI * 2);
                ctx.fill();

                // Subtle rim light
                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1.2;
                ctx.stroke();

                // Specular highlight
                ctx.fillStyle = 'rgba(255,255,255,0.55)';
                ctx.beginPath();
                ctx.arc(x - r * 0.28, y - r * 0.32, r * 0.22, 0, Math.PI * 2);
                ctx.fill();

                // Secondary softer highlight
                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                ctx.beginPath();
                ctx.arc(x - r * 0.1, y - r * 0.45, r * 0.1, 0, Math.PI * 2);
                ctx.fill();
            }

            // ─────────────────────────────────────
            // Physics Step
            // ─────────────────────────────────────
            function physicsStep(dt) {
                const n = Math.max(1, Math.ceil(dt / MAX_SUBSTEP));
                const subDt = dt / n;

                for (let s = 0; s < n; s++) {
                    for (const ball of balls) {
                        // Apply gravity
                        ball.vy += GRAVITY * subDt;

                        // Update position
                        ball.x += ball.vx * subDt;
                        ball.y += ball.vy * subDt;

                        // Bounce off left wall
                        if (ball.x - ball.r < 0) {
                            ball.x = ball.r;
                            if (Math.abs(ball.vx) < 0.5) {
                                ball.vx = 0;
                            } else {
                                ball.vx = -ball.vx * RESTITUTION;
                            }
                        }
                        // Bounce off right wall
                        if (ball.x + ball.r > CANVAS_SIZE) {
                            ball.x = CANVAS_SIZE - ball.r;
                            if (Math.abs(ball.vx) < 0.5) {
                                ball.vx = 0;
                            } else {
                                ball.vx = -ball.vx * RESTITUTION;
                            }
                        }
                        // Bounce off top wall
                        if (ball.y - ball.r < 0) {
                            ball.y = ball.r;
                            if (Math.abs(ball.vy) < 0.5) {
                                ball.vy = 0;
                            } else {
                                ball.vy = -ball.vy * RESTITUTION;
                            }
                        }
                        // Bounce off bottom wall
                        if (ball.y + ball.r > CANVAS_SIZE) {
                            ball.y = CANVAS_SIZE - ball.r;
                            if (Math.abs(ball.vy) < 0.5) {
                                ball.vy = 0;
                            } else {
                                ball.vy = -ball.vy * RESTITUTION;
                            }
                        }
                    }
                }
            }

            // ─────────────────────────────────────
            // Programmatic API (exposed on window.sim)
            // ─────────────────────────────────────
            window.sim = {
                w: CANVAS_SIZE,
                h: CANVAS_SIZE,

                balls() {
                    return balls.map(b => ({
                        x: b.x,
                        y: b.y,
                        vx: b.vx,
                        vy: b.vy,
                        r: b.r,
                    }));
                },

                addBall(x, y, vx = 0, vy = 0, r = DEFAULT_RADIUS) {
                    // Clamp position to keep ball fully inside canvas
                    const clampedX = Math.max(r, Math.min(CANVAS_SIZE - r, x));
                    const clampedY = Math.max(r, Math.min(CANVAS_SIZE - r, y));
                    balls.push({
                        x: clampedX,
                        y: clampedY,
                        vx: vx,
                        vy: vy,
                        r: r,
                        color: randomBallColor(),
                    });
                    // Render immediately so the ball appears even if paused
                    render();
                },

                clear() {
                    balls.length = 0;
                    render();
                },

                step(dt = 1) {
                    physicsStep(dt);
                    render();
                },
            };

            // ─────────────────────────────────────
            // Animation Loop
            // ─────────────────────────────────────
            function animate(timestamp) {
                if (!animating) return;
                if (lastTime === null) lastTime = timestamp;
                const rawDt = (timestamp - lastTime) / 1000; // seconds
                const dt = Math.min(rawDt, 0.1); // cap to avoid huge jumps
                lastTime = timestamp;
                physicsStep(dt);
                render();
                animationId = requestAnimationFrame(animate);
            }

            function startAnimation() {
                if (animating) return;
                animating = true;
                lastTime = null;
                updatePlayButton();
                animationId = requestAnimationFrame(animate);
            }

            function stopAnimation() {
                if (!animating) return;
                animating = false;
                if (animationId) {
                    cancelAnimationFrame(animationId);
                    animationId = null;
                }
                updatePlayButton();
            }

            function toggleAnimation() {
                if (animating) {
                    stopAnimation();
                } else {
                    startAnimation();
                }
            }

            function updatePlayButton() {
                if (animating) {
                    playBtn.textContent = '⏸ Pause';
                    playBtn.classList.remove('paused');
                } else {
                    playBtn.textContent = '▶ Play';
                    playBtn.classList.add('paused');
                }
            }

            // ─────────────────────────────────────
            // Event Handlers
            // ─────────────────────────────────────
            dropBtn.addEventListener('click', () => {
                const r = DEFAULT_RADIUS + Math.random() * 10; // varied radius
                const x = r + Math.random() * (CANVAS_SIZE - 2 * r);
                const y = r + 5;
                const vx = (Math.random() - 0.5) * 120;
                const vy = Math.random() * -40 - 10;
                window.sim.addBall(x, y, vx, vy, r);
            });

            playBtn.addEventListener('click', toggleAnimation);

            clearBtn.addEventListener('click', () => {
                window.sim.clear();
            });

            canvas.addEventListener('click', (e) => {
                const rect = canvas.getBoundingClientRect();
                const scaleX = CANVAS_SIZE / rect.width;
                const scaleY = CANVAS_SIZE / rect.height;
                const x = (e.clientX - rect.left) * scaleX;
                const y = (e.clientY - rect.top) * scaleY;
                const r = DEFAULT_RADIUS + Math.random() * 8;
                const vx = (Math.random() - 0.5) * 150;
                const vy = (Math.random() - 0.5) * 80 - 60;
                window.sim.addBall(x, y, vx, vy, r);
            });

            // Prevent double-tap zoom on canvas (mobile)
            canvas.addEventListener('touchstart', (e) => {
                if (e.touches.length > 1) e.preventDefault();
            }, { passive: false });

            // ─────────────────────────────────────
            // Initialize
            // ─────────────────────────────────────
            function init() {
                // Add a couple of starter balls
                window.sim.addBall(120, 80, 70, -90, 20);
                window.sim.addBall(380, 200, -100, 60, 16);
                window.sim.addBall(250, 400, 40, -150, 22);

                // Start animation
                updatePlayButton();
                lastTime = null;
                animationId = requestAnimationFrame(animate);
            }

            init();

            console.log('🟢 Bouncing Ball Physics Playground ready.');
            console.log('   API available at window.sim');
            console.log('   Canvas:', CANVAS_SIZE + '×' + CANVAS_SIZE, 'pixels');
            console.log('   Try: sim.addBall(250, 100, 50, -100, 20)');
            console.log('        sim.step(1)');
            console.log('        sim.balls()');
            console.log('        sim.clear()');
        })();
    </script>
</body>
</html>
